// Service
@Service class UrlShortenerService {
    private static final String CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    @Autowired UrlRepository repo;
    @Autowired RedisTemplate<String,String> redis;

    public String shorten(String longUrl, Long userId) {
        String code = toBase62(repo.save(new UrlMapping(longUrl, userId)).getId());
        redis.opsForValue().set("url:"+code, longUrl, 7, TimeUnit.DAYS);
        return "https://mmt.to/" + code;
    }

    public String resolve(String code, Long requestUserId) {
        String cached = redis.opsForValue().get("url:"+code);
        if (cached != null) return cached;
        UrlMapping mapping = repo.findByShortCode(code)
            .orElseThrow(() -> new NotFoundException());
        if (!mapping.getUserId().equals(requestUserId)) throw new ForbiddenException();
        return mapping.getLongUrl();
    }

    private String toBase62(long n) {
        StringBuilder sb = new StringBuilder();
        while (n > 0) { sb.append(CHARS.charAt((int)(n%62))); n/=62; }
        return sb.reverse().toString();
    }
}

@Service class BankService {
    private final Map<Long, Account> accounts = new ConcurrentHashMap<>();

    public Account createAccount(String owner) {
        Account acc = new Account(idGen.incrementAndGet(), owner);
        accounts.put(acc.getId(), acc);
        return acc;
    }

    public void deposit(long id, double amount) {
        Account acc = getOrThrow(id);
        synchronized(acc) { acc.setBalance(acc.getBalance() + amount); }
    }

    public void withdraw(long id, double amount) {
        Account acc = getOrThrow(id);
        synchronized(acc) {
            if (acc.getBalance() < amount) throw new InsufficientFundsException();
            acc.setBalance(acc.getBalance() - amount);
        }
    }

    public void transfer(long fromId, long toId, double amount) {
        // Lock in consistent order to prevent deadlock
        Account first  = fromId < toId ? getOrThrow(fromId) : getOrThrow(toId);
        Account second = fromId < toId ? getOrThrow(toId)   : getOrThrow(fromId);
        synchronized(first) {
            synchronized(second) {
                withdraw(fromId, amount);
                deposit(toId, amount);
            }
        }
    }
}

interface FizzBuzzRule {
    boolean matches(int n);
    String output();
}

class FizzRule    implements FizzBuzzRule { public boolean matches(int n){ return n%3==0; } public String output(){ return "Fizz"; } }
class BuzzRule    implements FizzBuzzRule { public boolean matches(int n){ return n%5==0; } public String output(){ return "Buzz"; } }
class WoofRule    implements FizzBuzzRule { public boolean matches(int n){ return n%7==0; } public String output(){ return "Woof"; } }

class FizzBuzzEngine {
    private final List<FizzBuzzRule> rules;
    FizzBuzzEngine(List<FizzBuzzRule> rules) { this.rules = rules; }

    public String evaluate(int n) {
        String result = rules.stream()
            .filter(r -> r.matches(n))
            .map(FizzBuzzRule::output)
            .collect(Collectors.joining());
        return result.isEmpty() ? String.valueOf(n) : result;
    }
}
