// Unified interface
interface RestaurantAdapter {
    List<MenuItem> search(String query);
}

// Restaurant 1 has different response format
class Restaurant1Adapter implements RestaurantAdapter {
    private Restaurant1Client client;
    public List<MenuItem> search(String query) {
        Restaurant1Response resp = client.getMenu(new Restaurant1Request(query));
        return resp.getDishes().stream()
            .map(d -> new MenuItem(d.getName(), d.getCost(), "Restaurant1"))
            .collect(Collectors.toList());
    }
}

// Facade aggregating all adapters
@Service class FoodSearchService {
    private final List<RestaurantAdapter> adapters;

    public List<MenuItem> search(String query) {
        return adapters.parallelStream()   // parallel for latency
            .flatMap(a -> a.search(query).stream())
            .collect(Collectors.toList());
    }
}
